CREATE FUNCTION public.profile_auth_session_id() RETURNS uuid LANGUAGE sql STABLE SET search_path=public AS $$ SELECT COALESCE(NULLIF(auth.jwt()->>'session_id','')::uuid, CASE WHEN auth.uid() IS NOT NULL THEN md5(auth.jwt()::text)::uuid END) $$;
GRANT EXECUTE ON FUNCTION public.profile_auth_session_id() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.customer_profile_restricted() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profile_session_access WHERE session_id=public.profile_auth_session_id() AND user_id=auth.uid() AND restricted) $$;
ALTER POLICY "read own session scope" ON public.profile_session_access USING (user_id=auth.uid() AND session_id=public.profile_auth_session_id());
CREATE OR REPLACE FUNCTION public.my_profile_access() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.profile_session_access; rs jsonb; staff boolean; BEGIN SELECT * INTO s FROM public.profile_session_access WHERE session_id=public.profile_auth_session_id() AND user_id=auth.uid(); SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('admin','management','staff','moderator')) INTO staff; SELECT COALESCE(jsonb_agg(role::text),'[]'::jsonb) INTO rs FROM public.user_roles WHERE user_id=auth.uid() AND (NOT COALESCE(s.restricted,false) OR role::text NOT IN ('admin','management','staff','moderator','boro_fan_zone_moderator')); IF COALESCE(s.restricted,false) AND staff THEN rs=rs || '["subscriber"]'::jsonb; END IF; RETURN jsonb_build_object('profileId',s.credential_id,'restricted',COALESCE(s.restricted,false),'canUseStaff',staff,'roles',rs); END $$;
CREATE OR REPLACE FUNCTION public.select_customer_profile(_credential uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE c private.app_credentials; sid uuid; restricted_now boolean; staff boolean; BEGIN sid=public.profile_auth_session_id(); IF auth.uid() IS NULL OR sid IS NULL THEN RAISE EXCEPTION 'Verified session required'; END IF; SELECT * INTO c FROM private.app_credentials WHERE id=_credential AND owner_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Choose your own profile'; END IF; SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('admin','management','staff','moderator')) INTO staff; SELECT restricted INTO restricted_now FROM public.profile_session_access WHERE session_id=sid AND user_id=auth.uid(); IF staff AND c.account_number=1 AND COALESCE(restricted_now,false) THEN RAISE EXCEPTION 'Account password required to restore staff access'; END IF; INSERT INTO public.profile_session_access(session_id,user_id,credential_id,restricted) VALUES(sid,auth.uid(),c.id,staff AND c.account_number<>1) ON CONFLICT(session_id) DO UPDATE SET credential_id=excluded.credential_id,restricted=excluded.restricted,updated_at=now(); RETURN public.my_profile_access(); END $$;